import{c as a,Q as l,j as A,m as s}from"./chunks/framework.DOi4mjdC.js";const e="/assets/1-84.DUMvKy6u.png",n="data:image/png;base64,",p="/assets/4.Ip9s4YvB.png",i="/assets/5.BQaynh6l.png",r="/assets/5-85.DPFVPSMG.png",m="/assets/%E8%AE%A1%E7%AE%97bound%E7%A4%BA%E6%84%8F%E5%9B%BE.2F7rWbmN.png",u="/assets/%E9%80%9A%E4%BF%A1bound%E7%A4%BA%E6%84%8F%E5%9B%BE.D7dxuKFf.png",o="data:image/png;base64,",g="/assets/mc2excel2.DuFP7y2T.png",x=JSON.parse('{"title":"MC²算子性能调优案例","description":"","frontmatter":{},"headers":[{"level":1,"title":"MC²算子性能调优案例","slug":"mc算子性能调优案例"},{"level":2,"title":"案例介绍","slug":"案例介绍"},{"level":2,"title":"获取性能数据","slug":"获取性能数据"},{"level":2,"title":"分析主要瓶颈点","slug":"分析主要瓶颈点"},{"level":2,"title":"设计优化方案","slug":"设计优化方案"},{"level":2,"title":"验证优化方案性能收益","slug":"验证优化方案性能收益"},{"level":2,"title":"总结","slug":"总结"}],"relativePath":"guide/算子实践参考/优秀实践/MC-算子性能调优案例.md","filePath":"guide/算子实践参考/优秀实践/MC-算子性能调优案例.md"}'),c={name:"guide/算子实践参考/优秀实践/MC-算子性能调优案例.md"};function M(d,t,b,f,P,N){return l(),A("div",null,[...t[0]||(t[0]=[s('<h1 id="mc2算子性能调优案例" tabindex="-1">MC²算子性能调优案例 <a class="header-anchor" href="#mc2算子性能调优案例" aria-label="Permalink to &quot;MC²算子性能调优案例&quot;">​</a></h1><h2 id="案例介绍" tabindex="-1">案例介绍 <a class="header-anchor" href="#案例介绍" aria-label="Permalink to &quot;案例介绍&quot;">​</a></h2><p>MC&lt;sup&gt;2&lt;/sup&gt;通算融合算子的性能收益主要来自于通信、计算的并行执行，即将输入数据切分为多个子块，子块的计算和通信任务形成两条流水线，通过两条流水线上任务的并行执行，实现流水掩盖，从而提升算子性能。如下图所示，MC&lt;sup&gt;2&lt;/sup&gt;算子先做Matmul计算、后通信的场景，输入矩阵沿M轴被切分为两块，第二块数据的Matmul计算和第一块数据的通信可以并行执行，从而达到计算和通信时间相互掩盖的目的。本节的所有图示中MM代表Matmul计算，hcom代表通信任务。</p><p><img src="'+e+'" alt=""></p><p>本案例将介绍如何分析通算融合算子的性能收益、如何制定较好的数据切分策略。更多MC&lt;sup&gt;2&lt;/sup&gt;算子的完整样例请参考<a href="https://gitcode.com/cann/ops-transformer/tree/master/mc2/matmul_all_reduce" target="_blank" rel="noreferrer">MatmulAllReduce样例</a>、<a href="https://gitcode.com/cann/ops-transformer/tree/master/mc2/matmul_reduce_scatter_v2" target="_blank" rel="noreferrer">MatmulReduceScatter样例</a>、<a href="https://gitcode.com/cann/ops-transformer/tree/master/mc2/all_gather_matmul_v2" target="_blank" rel="noreferrer">AllGatherMatmul样例</a>。</p><h2 id="获取性能数据" tabindex="-1">获取性能数据 <a class="header-anchor" href="#获取性能数据" aria-label="Permalink to &quot;获取性能数据&quot;">​</a></h2><p>通过msProf算子调优工具获取算子性能数据：</p><ul><li>获取<a href="./../性能分析/获取性能数据.html#section17953123893415">真实环境执行的性能数据</a>，包含各个流水的占比情况；</li><li>获取仿真性能数据（指令流水图），包含各个流水的占用区间，可观察流水间依赖情况，从而优化并行效率。</li></ul><h2 id="分析主要瓶颈点" tabindex="-1">分析主要瓶颈点 <a class="header-anchor" href="#分析主要瓶颈点" aria-label="Permalink to &quot;分析主要瓶颈点&quot;">​</a></h2><p>MC&lt;sup&gt;2&lt;/sup&gt;算子性能收益公式为：</p><p>融合前算子串行耗时 = 融合前计算算子耗时 + 融合前通信算子耗时</p><p>MC&lt;sup&gt;2&lt;/sup&gt;算子收益 = (融合前算子串行耗时 - 融合后MC&lt;sup&gt;2&lt;/sup&gt;算子耗时) / 融合前算子串行耗时</p><p>融合后MC&lt;sup&gt;2&lt;/sup&gt;算子的执行耗时，受以下因素制约，从而影响算子性能收益。</p><ul><li><p>因素一：计算和通信的执行时间差异</p><p>若计算和通信任务的执行时间相差不大，则融合后，MC&lt;sup&gt;2&lt;/sup&gt;算子的计算和通信并行执行，实现流水掩盖效果，性能收益较大。</p><p>若计算和通信任务的执行时间差异较大，则融合后，MC&lt;sup&gt;2&lt;/sup&gt;算子内计算和通信并行执行，能够掩盖的时间较少，算子整体执行耗时与未切分串行时的算子执行耗时接近，此时无法获得较大性能收益。</p><p><img src="'+n+'" alt=""></p></li><li><p>因素二：数据切分导致的计算或通信的执行时间膨胀</p><p>当对输入数据进行切分后，原本的整块数据被切分成若干小数据块，对若干小数据块分别做Matmul计算或者执行通信任务，此时相比切分前，计算或者通信任务的执行时间可能发生膨胀（即执行时间变长）。该膨胀产生的原因包括：切分后的数据块过小导致计算或通信的效率降低、切分的数据块过多导致增加额外的调度开销、并行执行后计算和通信对L2 Cache或device存储内存的访问冲突等。以Matmul计算为例，简单说明数据切分后执行时间可能发生的膨胀情况。</p><ul><li><p>未发生膨胀：</p><p>数据切分前，Matmul执行时间为200us，将Matmul的输入均匀切分为两块，假设切分后，每块数据的Matmul执行时间都是100us，通过计算的并行执行，下图实际性能收益为100us。</p><p><img src="'+p+'" alt=""></p></li><li><p>发生一般程度的膨胀：</p><p>数据切分前，Matmul执行时间为200us，将Matmul的输入均匀切分为两块，假设切分后，每块数据的Matmul执行时间都是150us，通过计算的并行执行，下图实际性能收益为50us。</p><p><img src="'+i+'" alt=""></p></li><li><p>发生严重程度的膨胀：</p><p>数据切分前，Matmul执行时间为200us，将Matmul的输入均匀切分为两块，假设切分后，每块数据的Matmul执行时间都是200us，通过计算的并行执行，下图实际性能收益为劣化50us。</p><p><img src="'+r+'" alt=""></p></li></ul></li></ul><p>综合上述分析，计算和通信执行时间较均衡的场景，有更好的流水掩盖和性能收益；同时，性能收益也受到数据切分导致的执行时间膨胀的影响。下文将介绍如何制定数据切分策略，以达到最佳流水掩盖效果。</p><h2 id="设计优化方案" tabindex="-1">设计优化方案 <a class="header-anchor" href="#设计优化方案" aria-label="Permalink to &quot;设计优化方案&quot;">​</a></h2><p>以Atlas A2 训练系列产品/Atlas A2 推理系列产品，输入数据格式为ND、数据类型为half的MatmulAllReduce算子为例，该算子中计算执行在前，通信任务执行在后。假定Matmul计算中左矩阵的形状为[M, K]，右矩阵的形状为[K, N]，算子中的通信对象为Matmul的输出矩阵，则通信任务的输入shape为[M, N]。因为K轴只在Matmul计算中存在，当K轴较大时，计算量大，计算执行时间大于通信执行时间，此时计算为算子的瓶颈（bound）；反之，当K轴较小时，计算量小，计算执行时间小于通信执行时间，此时通信为算子的瓶颈。在制定数据切分策略前，对原始矩阵分别执行计算和通信任务，根据两个任务的执行时间判定bound场景。</p><p>该算子的数据切分策略应满足如下要求：</p><ul><li>只切分M轴。因为通信任务调用的Hccl API要求分块数据内存连续，若按N轴切分，则每行数据都被切断，导致通信数据的内存不连续，不满足通信要求；若按M轴切分，则每行数据都是内存连续的，满足通信要求。</li><li>若A表示长块、B表示短块，只能切出A或B连续排布的形式，例如AAAB、BAAA等情况。</li></ul><p>如上文所述，数据切分的目标是达成尽可能多的流水掩盖。根据计算与通信任务的执行时间差异，实际场景可以分解为如下两个具体场景，两个场景有各自细分的切分目标。</p><ul><li><p>计算bound：</p><p>对于同一个切分后的数据块，计算执行耗时大于通信执行耗时，此时，<strong>计算连续</strong>，且<strong>通信的尾块要短</strong>，如下图所示。</p><p><strong>图 1</strong> 计算bound示意图<br><img src="'+m+'" alt="" title="计算bound示意图"></p></li><li><p>通信bound：</p><p>对于同一个切分后的数据块，通信执行耗时大于计算执行耗时，此时，<strong>通信连续</strong>，且<strong>计算的头块要短</strong>，如下图所示。</p><p><strong>图 2</strong> 通信bound示意图<br><img src="'+u+'" alt="" title="通信bound示意图"></p></li></ul><p><strong>前置工作：</strong></p><p>在进行最终的数据切分前，需要做的前置工作有：判定bound场景、分别对Matmul计算和AllReduce通信的数据量与执行时间关系做公式拟合。具体步骤如下。</p><ol><li><p>将输入数据分别单独执行Matmul计算和AllReduce通信任务，利用msProf工具分别采集执行时间，判定时间较长的任务为对应的bound场景。例如通信执行时间大于计算执行时间，则为<a href="#fig19667165810312">通信bound场景</a>。</p></li><li><p>将输入数据按M轴切分，分别切成M轴为256、512、768、1024、2048的若干数据块，这里可以根据实际情况调整切块大小。</p></li><li><p>将步骤2得到的数据块分别做AllReduce通信，利用msProf工具采集执行时间，得到每个数据块的执行时间t&lt;sub&gt;1&lt;/sub&gt;, t&lt;sub&gt;2&lt;/sub&gt;, ..., t&lt;sub&gt;n&lt;/sub&gt;。然后，作图分析数据量与对应的执行时间的关系，拟合得到公式t = CostComm(m)，其中m表示数据块的M轴长度，t表示数据块的通信执行时间，CostComm表示拟合得到的m和t的映射关系。该映射关系一般为线性，若不满足线性关系，可以采用分段拟合的方式。示例如下：</p><p><img src="'+o+'" alt=""></p><p><img src="'+g+`" alt=""></p><p>数据量x = m * N * sizeof(dataType)，单位是Bytes。该拟合公式表示为：</p><ul><li>x小于8MB：t = -0.9698202 * x * x + 27.0622573 * x + 14.769，单位是us。</li><li>x大于等于8MB：t = 13.58491263 * x + 61.508333，单位是us。</li></ul></li><li><p>将步骤2切分得到的各数据块做Matmul计算，按与步骤3相同的方式采集各数据块的计算执行时间t，并拟合得到M轴长度和计算执行时间关系的公式t = CostMM(m)，CostMM是拟合得到的m和t的映射关系。</p></li></ol><p><strong>切分算法步骤：</strong></p><ol><li><p>根据输入矩阵的shape：M、K、N，按照经验值设置合适的M轴方向切分的短块长度。如下表达式中，a、b、c表示根据经验值给出的短块长度的备选，将K、N带入如下三个表达式后，取a、b、c的最小值m0为选定的短块长度。</p><ul><li>a * K * N &gt;= 4 * 1024 * 1024 * 1024，a取不等式的最小值</li><li>b * K * N / 1024 + b * N &gt;= 6 * 1024 * 1024，b取不等式的最小值</li><li>c &gt;= 3 * 128，c取不等式的最小值</li><li>m0 = min(a, b, c)</li></ul></li><li><p>根据短块长度m0和拟合公式，分别得到计算执行时间t0 = CostMM(m0) * 1.15，通信执行时间t1 = CostComm(m0) * 1.15。</p><p>注意：通信和计算并行执行时，可能出现抢占内存带宽的情况，导致执行时间增加，一般按经验在拟合公式中乘以1.15的系数，用户可以根据实测情况调整该系数。</p></li><li><p>根据短块的长度，按<a href="#fig718114619319">图1</a>或<a href="#fig19667165810312">图2</a>配平通算，得到长块的长度，长块长度尽量对齐128个元素，以保证计算亲和。本案例为<a href="#fig19667165810312">通信bound场景</a>，这里的配平，即将短块的通信时间和长块的计算时间匹配相等：将t1作为长块的计算执行时间，带入t1 = CostMM(m1)公式，计算得到m1，即为长块的长度。</p></li><li><p>根据短块长度m0、长块长度m1、原始M轴长度M，得出长块的切块个数count = (M - m0) / m1。该式一般不能整除，此时需要做如下处理：</p><ul><li>将结果的小数部分舍弃，保留整数部分作为切块个数。</li><li>由于舍弃了小数部分，M轴长度有剩余，因此需要调整长块长度m1 = (M - m0) / count。</li><li>为保持计算亲和，将长块长度m1调整至128对齐，即向下取128倍数的整数，更新长块长度m1。</li><li>由于调整m1后，M轴长度有剩余，因此调整短块长度m0 = M - (m1 * count)。</li><li>最终得到短块长度m0，长块长度m1，长块个数count。</li></ul></li></ol><h2 id="验证优化方案性能收益" tabindex="-1">验证优化方案性能收益 <a class="header-anchor" href="#验证优化方案性能收益" aria-label="Permalink to &quot;验证优化方案性能收益&quot;">​</a></h2><ul><li><p>制定切分策略并验证性能收益</p><p>本MatmulAllReduce案例中，给定的输入矩阵Shape为M=4096，K=3072，N=8192，数据类型为half，分核数为8，通过融合前msProf工具采集，得到该输入的Matmul计算执行时间为803us，AllReduce通信的执行时间为1071us，总耗时1874us，属于通信bound场景。按照上述的切分算法，本案例的具体切分情况如下：</p><ol><li>根据经验值选定短块（bound场景中短块为头块，即切分后的第一个数据块）M方向长度m0为384，则通信数据量x为：384 * 8192 * 2 / 1024 / 1024 = 6MB。按<a href="#li1188918472441">通信拟合公式</a>估算通信的执行时间为143us。考虑可能会发生内存带宽冲突，因此再乘以1.15的系数，得出通信执行时间164us。</li><li>计算长块M方向长度。根据短块通信时间，配平长块的计算执行时间同样为164us，按计算拟合公式估算出该长度m1为768。</li><li>根据M=4096、m0=384、m1=768，计算长块个数：(4096 - 384) / 768 = 4.83，向下取整为4。</li><li>根据短块长度m0=384，长块个数4，调整长块m1长度：(4096 - 384) / 4 = 928，向下按128对齐，调整m1为896。</li><li>根据长块长度m1=896，长块个数4，调整短块m0长度：4096 - 896 * 4 = 512。</li><li>最终得到将原始输入矩阵切分为5个数据块，长度分别为：{512，896，896，896，896}。</li></ol><p>如下代码所示，在算子的Tiling代码中设置制定好的切分策略。按该切分策略测试，融合后该算子的执行时间为1262us，则融合算子的性能收益为(1874 - 1262) / 1874 = 32.7%。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MatmulAllReduceCustomTilingData *tiling = context-&gt;GetTilingData&lt;MatmulAllReduceCustomTilingData&gt;();</span></span>
<span class="line"><span>tiling-&gt;param.rankDim = 8;</span></span>
<span class="line"><span>tiling-&gt;param.tileM = 512; // 短块大小</span></span>
<span class="line"><span>tiling-&gt;param.tileNum = 1; // 短块个数</span></span>
<span class="line"><span>tiling-&gt;param.tailM = 896; // 长块大小</span></span>
<span class="line"><span>tiling-&gt;param.tailNum = 4; // 长块个数</span></span>
<span class="line"><span>tiling-&gt;param.rankM = 4096;</span></span>
<span class="line"><span>tiling-&gt;param.rankN = 8192;</span></span>
<span class="line"><span>tiling-&gt;param.rankK = 4096;</span></span>
<span class="line"><span>tiling-&gt;param.isTransposeA = 0;</span></span>
<span class="line"><span>tiling-&gt;param.isTransposeB = 0;</span></span>
<span class="line"><span>tiling-&gt;param.cToFloatLen = 0;</span></span>
<span class="line"><span>tiling-&gt;param.nd2NzWorkLen = true;</span></span>
<span class="line"><span>tiling-&gt;param.dataType = static_cast&lt;uint8_t&gt;(HCCL_DATA_TYPE_MAP.at(aType));</span></span></code></pre></div></li><li><p>针对切分膨胀做调整</p><p>上文提到，切分数据会引起计算或通信执行时间的膨胀，使实测结果与理论值有偏差。比如切块数量较多时，执行时间的膨胀对性能影响较大，可能导致性能收益变小或者出现性能劣化，因此最终需要根据上述理论切分策略，结合实测，对切分策略做调整。</p></li></ul><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>MC&lt;sup&gt;2&lt;/sup&gt;算子通过数据切分后计算和通信的并行执行，获得性能收益，但受数据切分后执行时间膨胀的影响。对MC&lt;sup&gt;2&lt;/sup&gt;算子进行性能调优的主要方式是制定数据切分策略，开发人员需要根据理论推导找到理想切分策略，然后根据实测结果调整，最终找到最优切分策略。</p>`,30)])])}const B=a(c,[["render",M]]);export{x as __pageData,B as default};
